#!/usr/bin/env python3
"""Install only the approved static support-chat files. No ERP/DNS/Caddy changes."""
import argparse
import base64
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import shutil
import stat
import tempfile

MANIFEST = json.loads('''{"assets/support-chat.js":{"previous":null,"sha256":"fd2a9f24f914bdb304c684a29467984973c171ebd360fc217af0e724c124efa0","data":""},"assets/support-contact-config.js":{"previous":"5ed7bf3df73f0300649530a83fdf908ccbda0d7a59996e4caada37a328962a18","sha256":"9e42a02662d3fa181aa44a51442cce68fddfa896fb15982b5dadd51cd4596e05","data":""},"assets/support-contacts.js":{"previous":"7962679f2f8fa7fd6e1ffbdef6cc3780822a18eee8487f40fd130dc8e5db4ab8","sha256":"52093e978a36f5a1e0705840a94041cb41951958960ff1b306b9aff99584b01a","data":""},"support/index.html":{"previous":"4d4e9cd9516fd9c15796496f26fe3935982439f550167fba8bf575eeb8558def","sha256":"502e877021f70f3a09429a07fb1dd89898027aced4250858b7d4c605d72bc399","data":""}}''')


def digest(data):
    return hashlib.sha256(data).hexdigest()


def atomic_write(path, data):
    fd, name = tempfile.mkstemp(prefix='.ff-chat-', dir=path.parent)
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(name, stat.S_IMODE(path.stat().st_mode) if path.exists() else 0o644)
        os.replace(name, path)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def activate(web):
    original, updated = {}, {}
    for relative, item in MANIFEST.items():
        path = web / relative
        if path.parent.is_symlink() or path.is_symlink():
            raise ValueError('Symlink refused: ' + relative)
        if not path.parent.is_dir() or (path.exists() and not path.is_file()):
            raise ValueError('Unexpected path: ' + relative)
        data = base64.b64decode(item['data'])
        if digest(data) != item['sha256']:
            raise ValueError('Invalid embedded release: ' + relative)
        old = path.read_bytes() if path.exists() else None
        if old == data:
            continue
        if (old is None and item['previous'] is not None) or (old is not None and digest(old) != item['previous']):
            raise ValueError('Unexpected existing file; refusing overwrite: ' + relative)
        original[path], updated[path] = old, data
    if not updated:
        return None
    backup = web.parent / 'backups' / ('support-chat-' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '-' + str(os.getpid()))
    backup.mkdir(parents=True, exist_ok=False)
    for path, old in original.items():
        if old is not None:
            dest = backup / path.relative_to(web)
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, dest)
    (backup / 'new-files.json').write_text(json.dumps([str(p.relative_to(web)) for p, old in original.items() if old is None]))
    changed = []
    try:
        for path, data in updated.items():
            atomic_write(path, data)
            changed.append(path)
    except Exception:
        for path in reversed(changed):
            if original[path] is None:
                path.unlink()
            else:
                atomic_write(path, original[path])
        raise RuntimeError('Activation failed; changed files restored. Backup: ' + str(backup))
    return backup


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--web', default='/opt/flavorflow-saas/web')
    args = parser.parse_args()
    if os.geteuid() != 0:
        parser.error('Run with sudo on the existing hosting VM.')
    try:
        backup = activate(Path(args.web).resolve())
    except (OSError, ValueError, RuntimeError) as error:
        parser.exit(1, str(error) + '\n')
    print('Support chat integration installed (click-to-load tawk.to).')
    print('Backup: ' + str(backup) if backup else 'Already installed; no files changed.')
    print('Email and phone preserved. No paid add-ons, backend changes or Caddy reload.')
    print('Open https://support.flavorflow.co.in/#contact-support and click Open live chat.')
    print('Send a test message and reply from your tawk.to dashboard to verify actual delivery.')


if __name__ == '__main__':
    main()
